// Prep batch items - pass through with 500ms delay for politeness
const items = $input.all();

// Small delay between batches
await new Promise(resolve => setTimeout(resolve, 500));

return items.map(item => {
  const data = item.json;
  return { json: { 
    page_id: data.page_id, 
    url: data.url, 
    domain_id: data.domain_id,
    domain: data.domain,
    clinic_id: data.clinic_id || null,
    priority_score: data.priority_score || 4
  }};
});

// Process all HTTP responses in this batch
return $input.all().map((inputItem, index) => {
  const resp = inputItem.json;

  // Get context from Prep Batch node
  const prepItems = $('Prep Batch').all();
  const prepData = prepItems[index]?.json || {};

  const url = prepData.url || resp.url || '';
  const page_id = prepData.page_id || '';
  const domain = prepData.domain || '';

  let statusCode = resp.statusCode || 200;
  let htmlBody = '';
  let error = null;

  // Handle binary/image responses
  if (resp.mimeType && !resp.mimeType.includes('text/html')) {
    return { json: { 
      url, page_id, domain,
      statusCode: 200, htmlBody: '', bytesReceived: 0, error: null,
      qualityGateFailed: true, qualityReason: 'not_html_mimetype',
      isSitemap: false, fetchMethod: 'http'
    }};
  }

  if (resp.error) {
    error = resp.error.message || String(resp.error);
    statusCode = resp.statusCode || 0;
  } else {
    htmlBody = resp.body || resp.data || '';
    if (typeof htmlBody === 'object' && htmlBody !== null) {
      htmlBody = JSON.stringify(htmlBody);
    }
  }

  htmlBody = String(htmlBody).substring(0, 200000);
  let bytesReceived = htmlBody ? htmlBody.length : 0;

  let qualityGateFailed = false;
  let qualityReason = '';
  let isSitemap = false;

  if (!htmlBody) {
    qualityGateFailed = true;
    qualityReason = 'empty_response';
  } else if (htmlBody.length < 500) {
    qualityGateFailed = true;
    qualityReason = 'too_short';
  } else if (htmlBody.trim().startsWith('<?xml') && (htmlBody.includes('<urlset') || htmlBody.includes('<sitemapindex'))) {
    qualityGateFailed = true;
    qualityReason = 'sitemap_xml';
    isSitemap = true;
  } else if (!htmlBody.includes('<') && !htmlBody.includes('>')) {
    qualityGateFailed = true;
    qualityReason = 'not_html';
  } else if (statusCode === 403) {
    qualityGateFailed = true;
    qualityReason = 'blocked';
  } else if (statusCode === 404) {
    qualityGateFailed = true;
    qualityReason = 'not_found';
  } else if (statusCode >= 500) {
    qualityGateFailed = true;
    qualityReason = 'server_error';
  }

  return { json: { 
    url, page_id, domain,
    statusCode, htmlBody, bytesReceived, error,
    qualityGateFailed, qualityReason, isSitemap,
    fetchMethod: 'http'
  }};
});

// Extract content and compute content hash in pure JavaScript
// Simple hash function (djb2 variant) that works in n8n sandbox
function simpleHash(str) {
  let hash = 5381;
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) + hash) + str.charCodeAt(i);
    hash = hash & hash; // Convert to 32-bit integer
  }
  // Convert to hex and pad to ensure consistent length
  const hex = Math.abs(hash).toString(16).padStart(8, '0');
  // Repeat to get 64-char hash-like string
  return (hex + hex + hex + hex + hex + hex + hex + hex).substring(0, 64);
}

return $input.all().map(inputItem => {
  const data = inputItem.json;
  const html = data.htmlBody || '';

  function stripHtml(htmlStr) {
    return htmlStr
      .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
      .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
      .replace(/<nav[^>]*>[\s\S]*?<\/nav>/gi, '')
      .replace(/<footer[^>]*>[\s\S]*?<\/footer>/gi, '')
      .replace(/<header[^>]*>[\s\S]*?<\/header>/gi, '')
      .replace(/<[^>]+>/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();
  }

  const textContent = stripHtml(html);
  const wordCount = textContent.split(/\s+/).filter(w => w.length > 0).length;
  const markdown = textContent.substring(0, 100000);
  const normalizedForHash = markdown.replace(/\s+/g, ' ').trim().toLowerCase();

  // Compute hash using pure JS function
  const contentHash = simpleHash(normalizedForHash || 'empty');

  return { json: {
    ...data,
    markdown,
    contentHash,
    wordCount
  }};
});

