// Merge results and continue to next batch
// Use try/catch to handle cases where branches didn't execute
let storedCount = 0;
let failedCount = 0;

try {
  const stored = $('Store Content').all();
  storedCount = stored.length;
} catch (e) {
  // Store Content branch didn't execute (no quality pages)
  storedCount = 0;
}

try {
  const failed = $('Log Failed Fetch').all();
  failedCount = failed.length;
} catch (e) {
  // Log Failed Fetch branch didn't execute (no failures)
  failedCount = 0;
}

return [{ json: { 
  batchComplete: true,
  stored: storedCount,
  failed: failedCount,
  total: storedCount + failedCount
}}];

// Summary of all batches
const allResults = $input.all();
const totalStored = allResults.reduce((sum, item) => sum + (item.json.stored || 0), 0);
const totalFailed = allResults.reduce((sum, item) => sum + (item.json.failed || 0), 0);

return [{ json: {
  workflow: 'W-4B Depth Crawl',
  timestamp: new Date().toISOString(),
  totalPages: totalStored + totalFailed,
  stored: totalStored,
  failed: totalFailed,
  status: 'complete'
}}];
